(1807586, 247345, 26255, '<td valign="top">Good shot, very fitting halloween shot. The image grain helps add to the shot.</td>', 'Good shot, very fitting halloween shot. The image grain helps add to the shot.', '2005-10-24 14:31:17.000000', NULL, 1),
(1807588, 245494, 26255, '<td valign="top">I really like this one.  Feels very surreal</td>', 'I really like this one.  Feels very surreal', '2005-10-24 14:31:53.000000', NULL, 1),
(1807592, 248035, 26255, '<td valign="top">Great shot.  I love the composition and the subtle hues/low-key feeling of this.  Your model looks very relaxed.</td>', 'Great shot.  I love the composition and the subtle hues/low-key feeling of this.  Your model looks very relaxed.', '2005-10-24 14:32:49.000000', NULL, 1),
