(1809712, 248270, 44703, '<td valign="top">Terrific shot.</td>', 'Terrific shot.', '2005-10-25 08:31:15.000000', NULL, 1),
(1809714, 248244, 24920, '<td valign="top">Wow! Very nice. The sky looks very dramatic.</td>', 'Wow! Very nice. The sky looks very dramatic.', '2005-10-25 08:31:55.000000', NULL, 1),
(1809716, 246709, 7560, '<td valign="top">The grain is highly effective here, but the figure in the foreground is overly sharp. When/if you repost process this one it might help to not sharpen him when sharpening the rest of the image. Very cool shot. 7</td>', 'The grain is highly effective here, but the figure in the foreground is overly sharp. When/if you repost process this one it might help to not sharpen him when sharpening the rest of the image. Very cool shot. 7', '2005-10-25 08:32:21.000000', NULL, 1),
