(1809719, 247266, 44703, '<td valign="top">Terrific shot, very nice photo.</td>', 'Terrific shot, very nice photo.', '2005-10-25 08:34:26.000000', NULL, 1),
(1809720, 247606, 44703, '<td valign="top">Nice, the rain adds some great natural noise.</td>', 'Nice, the rain adds some great natural noise.', '2005-10-25 08:36:28.000000', NULL, 1),
