(1811847, 245659, 37961, '<td valign="top">You could have went with more grain on this and made me happy. Love the colors and lighting.</td>', 'You could have went with more grain on this and made me happy. Love the colors and lighting.', '2005-10-25 19:53:34.000000', NULL, 1),
(1811852, 245561, 37961, '<td valign="top">Clever.</td>', 'Clever.', '2005-10-25 19:54:02.000000', NULL, 1),
(1811858, 246937, 37961, '<td valign="top">Gotta love a grainy doggy photo. I know that look well....they are tired! Whew. 7.</td>', 'Gotta love a grainy doggy photo. I know that look well....they are tired! Whew. 7.', '2005-10-25 19:55:09.000000', NULL, 1),
