(1811920, 245970, 35218, '<td valign="top">Hmmm.  Nice enough shot but lacks a strong subject and not clear to me why the grain is relevant here.</td>', 'Hmmm.  Nice enough shot but lacks a strong subject and not clear to me why the grain is relevant here.', '2005-10-25 20:10:08.000000', NULL, 1),
(1811922, 248083, 35218, '<td valign="top">Nice door detail.  Grain certainly helps.  Wish the lock was a bit more clearly defined.</td>', 'Nice door detail.  Grain certainly helps.  Wish the lock was a bit more clearly defined.', '2005-10-25 20:10:59.000000', NULL, 1),
(1811926, 248491, 35218, '<td valign="top">Very nicely done.</td>', 'Very nicely done.', '2005-10-25 20:12:08.000000', NULL, 1),
(1811931, 248375, 35218, '<td valign="top">Like the grain and the abstract feel.  A bit too busy for my taste with an insufficiently strong subject.</td>', 'Like the grain and the abstract feel.  A bit too busy for my taste with an insufficiently strong subject.', '2005-10-25 20:13:10.000000', NULL, 1),
(1811934, 246759, 35218, '<td valign="top">I have a personal dislike of formally arranged still life shots.  But, putting that aside, I like this one.  The desaturation is effective and the warm sheaves work very well.</td>', 'I have a personal dislike of formally arranged still life shots.  But, putting that aside, I like this one.  The desaturation is effective and the warm sheaves work very well.', '2005-10-25 20:15:06.000000', NULL, 1),
(1811936, 245496, 32602, '<td valign="top">brickwork, rust  &amp; grain, a terrific combo, the light is great too</td>', 'brickwork, rust  & grain, a terrific combo, the light is great too', '2005-10-25 20:15:13.000000', NULL, 1),
(1811940, 248125, 35218, '<td valign="top">Nicely set up</td>', 'Nicely set up', '2005-10-25 20:15:31.000000', NULL, 1),
