(1811961, 248126, 35218, '<td valign="top">Nice shot.  Would have been better without the hand and the distracting sleeve.</td>', 'Nice shot.  Would have been better without the hand and the distracting sleeve.', '2005-10-25 20:21:10.000000', NULL, 1),
(1811962, 248386, 36988, '<td valign="top">nice image... perhaps a little lighter background but well done<br/></td>', 'nice image... perhaps a little lighter background but well done', '2005-10-25 20:21:38.000000', NULL, 1),
