INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1817317, 246796, 35602, '<td valign="top">Very dramatic sky.  Thought the foreground and lower part of the picture was a little dark.</td>', 'Very dramatic sky.  Thought the foreground and lower part of the picture was a little dark.', '2005-10-27 07:28:39.000000', NULL, 1),
(1817320, 247909, 35602, '<td valign="top">Liked the mood created by the single light on the background trees.  Seemed a little too broken up, though.  If you did not use a tripod, it would have made the image somewhat clearer.  It may have been oversharpened to create grain.</td>', 'Liked the mood created by the single light on the background trees.  Seemed a little too broken up, though.  If you did not use a tripod, it would have made the image somewhat clearer.  It may have been oversharpened to create grain.', '2005-10-27 07:31:23.000000', NULL, 1),
(1817321, 248228, 35602, '<td valign="top">Used grain well, but as a pleasing picture, I am afraid for me it was lost.</td>', 'Used grain well, but as a pleasing picture, I am afraid for me it was lost.', '2005-10-27 07:32:28.000000', NULL, 1),
(1817322, 248441, 35602, '<td valign="top">Really loved this picture.  Looks so much like a painting, and definitely gives a feel of an artist thinking about his work.  The only thing that might have supported the image better was perhaps a brush in his hand, to really match the title, or maybe placing an unfinished canvas behind him as a background.</td>', 'Really loved this picture.  Looks so much like a painting, and definitely gives a feel of an artist thinking about his work.  The only thing that might have supported the image better was perhaps a brush in his hand, to really match the title, or maybe placing an unfinished canvas behind him as a background.', '2005-10-27 07:34:24.000000', NULL, 1),
(1817381, 248175, 45965, '<td valign="top">I love the left half with the frosty flower, but don''t really like the distracting flowers on the right hand side. I''d suggest toning those down. Even better maybe, crop tighter on the main subject and clone out the pink blossom(s).</td>', 'I love the left half with the frosty flower, but don''t really like the distracting flowers on the right hand side. I''d suggest toning those down. Even better maybe, crop tighter on the main subject and clone out the pink blossom(s).', '2005-10-27 08:33:20.000000', NULL, 1),
(1817395, 247522, 45965, '<td valign="top">In this case I think the picture would be better without the selective coloring, or at least toned down some.  Lke the composition, pose and begging eyes.</td>', 'In this case I think the picture would be better without the selective coloring, or at least toned down some.  Lke the composition, pose and begging eyes.', '2005-10-27 08:44:03.000000', NULL, 1),
(1817407, 248527, 45965, '<td valign="top">Very nice image, great light, but I''m not sure I like the composition. I''d like to crop just a little bit off the left side.</td>', 'Very nice image, great light, but I''m not sure I like the composition. I''d like to crop just a little bit off the left side.', '2005-10-27 08:50:33.000000', NULL, 1),
(1817483, 247819, 4226, '<td valign="top">the border/framing is grabbing too much attention</td>', 'the border/framing is grabbing too much attention', '2005-10-27 09:55:25.000000', NULL, 1),
(1817538, 248080, 25159, '<td valign="top">I really like how this was done. The grain fits nicely in this scene.</td>', 'I really like how this was done. The grain fits nicely in this scene.', '2005-10-27 10:34:09.000000', NULL, 1),
