(1825680, 248269, 41522, '<td valign="top">This is really nice.  A comfortable feeling in this shot.  Somehow, I get the feeling of old fashioned morals in this shot.  Extremely well processed.  Very nicely composed.  Good tones and the grain is a nice moody value add.</td>', 'This is really nice.  A comfortable feeling in this shot.  Somehow, I get the feeling of old fashioned morals in this shot.  Extremely well processed.  Very nicely composed.  Good tones and the grain is a nice moody value add.', '2005-10-30 22:52:40.000000', NULL, 1),
(1825685, 248125, 22734, '<td valign="top">A tender and well composed b/w study. I love the hair as it winds and contained by the fingers.</td>', 'A tender and well composed b/w study. I love the hair as it winds and contained by the fingers.', '2005-10-30 22:54:01.000000', NULL, 1),
(1825687, 245640, 41522, '<td valign="top">Quite the shot.  Well done.  The selective desat is a nice touch.  The grain on this adds to a mood that this might have actually been captured in the early 1900s.  Good work.</td>', 'Quite the shot.  Well done.  The selective desat is a nice touch.  The grain on this adds to a mood that this might have actually been captured in the early 1900s.  Good work.', '2005-10-30 22:55:04.000000', NULL, 1),
